WITH exploded AS (SELECT id, created_at, coupon_codes, li_item.qty, li_item.price, li_item.promo FROM (SELECT id, created_at, coupon_codes, EXPLODE_OUTER(items) AS li_item FROM carts) li) SELECT qty, price, promo, CUME_DIST() OVER (ORDER BY qty DESC NULLS FIRST) AS qty_cume_dist, ROUND(qty / SUM(qty) OVER (PARTITION BY promo), 4) AS qty_share, MAX(price) OVER (PARTITION BY promo) AS promo_max_price, PERCENT_RANK() OVER (ORDER BY price DESC NULLS FIRST) AS price_percent_rank FROM exploded
